"""Question validation before JSON encoding."""

from collections.abc import Mapping, Sequence

from typesafe_sdk._core.errors import TypeSafeError
from typesafe_sdk._core.json_types import JSONContent
from typesafe_sdk._core.question_types import Choice, Noul, Question, Score


def normalize_questions(questions: Mapping[str, Question]) -> dict[str, Question]:
    if not questions:
        raise TypeSafeError("At least one question is required.")
    for name, question in questions.items():
        if isinstance(question, Score):
            _validate_score_criteria(name, question.criteria)
        elif not isinstance(question, (Noul, Choice)):
            if not isinstance(question, dict) or not isinstance(question.get("type"), str) or not question["type"]:
                raise TypeSafeError(f'Question "{name}" must be a question object or a dictionary with a nonempty string "type".')
            if question["type"] in ("choice", "score") and "criteria" not in question:
                raise TypeSafeError(f'Question "{name}" requires "criteria".')
            if question["type"] == "score":
                _validate_score_criteria(name, question["criteria"])
    return dict(questions)


def _validate_score_criteria(name: str, criteria: Sequence[JSONContent]) -> None:
    """Reject a score question with no criteria; at least one score is required."""
    if not criteria:
        raise TypeSafeError(f'Score question "{name}" has no criteria; at least one score is required.')

"""JSON encoding and lenient response decoding, backed by pydantic-core's fast codec."""

from collections.abc import Mapping, Sequence
from typing import Any

from pydantic_core import from_json, to_json


def _fallback(value: object) -> object:
    """Materialize abstract input containers (any `Mapping`/`Sequence`) into JSON-encodable types.

    Public input types are declared as `Mapping`/`Sequence` so callers may pass, for example, a
    `MappingProxyType` or a custom mapping; pydantic-core's serializer encodes only concrete
    containers natively, so anything else is coerced here before it is re-serialized.
    """
    if isinstance(value, str):
        return str(value)
    if isinstance(value, Mapping):
        return dict(value)
    if isinstance(value, Sequence) and not isinstance(value, (str, bytes, bytearray)):
        return list(value)
    raise TypeError(f"Encoding objects of type {type(value).__name__} is unsupported")


def serialize(value: object) -> bytes:
    return to_json(value, fallback=_fallback)


def deserialize(content: bytes) -> Any:
    if not content:
        return None
    try:
        return from_json(content)
    except ValueError:
        return content.decode("utf-8", errors="replace")

def judge(self, query: str, candidates: list[Resource]) -> Judgment:
    state = {
        "user_goal": query,
        "candidates": {
            f"c{index}": {
                "name": resource.name,
                "description": resource.description,
                "use_when": resource.use_when,
                "avoid_when": resource.avoid_when,
            }
            for index, resource in enumerate(candidates)
        },
    }
    questions = {
        f"c{index}": self._noul(
            instructions=(
                f"Given `user_goal` and `candidates.c{index}`, can this resource "
                "directly perform the user's requested task within its declared capabilities?"
            ),
            criteria={
                "true": "The stated capability and intended use directly cover the task.",
                "false": (
                    "Only similar wording or a related topic, an excluded use, or insufficient "
                    "evidence of the required capability."
                ),
            },
        )
        for index in range(len(candidates))
    }
    started = perf_counter()
    with self._client_type() as client:
        response = client.system_one(state=state, questions=questions)
    elapsed = perf_counter() - started
    probabilities = {
        resource.id: float(response.answers[f"c{index}"].noul)
        for index, resource in enumerate(candidates)
    }

def jev_scores(
    case: Case,
    resources: list[Resource],
    *,
    bench: str,
    desc_provider: Callable[[Resource], str] | None = None,
) -> tuple[dict[str, float], dict]:
    from typesafe_sdk import Noul, TypeSafeClient

    resolve_desc: Callable[[Resource], str] = desc_provider or (
        lambda resource: resource.description[:JEV_DESCRIPTION_MAX_CHARS]
    )

    state = {
        "task": case.query,
        "retrieval_instruction": case.instruction if bench == "toolret" else "",
        "candidates": {
            f"c{index}": {
                "name": resource.name,
                "description": resolve_desc(resource),
                "tags": resource.tags,
            }
            for index, resource in enumerate(resources)
        },
    }
    questions = {
        f"c{index}": Noul(
            instructions=(
                f"Considering `task`, `retrieval_instruction`, and `candidates.c{index}`, "
                "is this resource suitable for at least one concrete step needed to "
                "fulfill the task? Judge its declared capability, not shared keywords."
            ),
            criteria={
                "true": "The resource can perform a specific operation needed for the task.",
                "false": "Only a related topic, a wrong operation, or insufficient stated capability.",
            },
        )
        for index in range(len(resources))
    }
    started = perf_counter()
    with TypeSafeClient() as client:
        response = client.system_one(state=state, questions=questions)
    elapsed = perf_counter() - started
    scores = {
        resource.id: float(response.answers[f"c{index}"].noul)
        for index, resource in enumerate(resources)
    }
    usage = {
        "model": response.model,
        "latency_seconds": elapsed,
        "input_tokens": response.usage.input_tokens,
        "output_tokens": response.usage.output_tokens,
    }
    return scores, usage


